alter table public.products add column if not exists gtin_ean text;
alter table public.products add column if not exists ncm text;
alter table public.products add column if not exists unit_measure text;
alter table public.products add column if not exists manufacturer_reference text;
alter table public.products add column if not exists regulatory_type text default 'ANVISA';
alter table public.products add column if not exists anvisa_status text;
alter table public.products add column if not exists anvisa_expiration_date date;
alter table public.products add column if not exists anvisa_risk_class text;
alter table public.products add column if not exists inmetro_register text;
alter table public.products add column if not exists inmetro_expiration_date date;
alter table public.products add column if not exists udi_di text;
alter table public.products add column if not exists lot_control boolean not null default true;
alter table public.products add column if not exists serial_control boolean not null default false;
alter table public.products add column if not exists expiration_control boolean not null default false;
alter table public.products add column if not exists shelf_life_months integer;
alter table public.products add column if not exists warranty_months integer;
alter table public.products add column if not exists intended_use text;
alter table public.products add column if not exists technical_specifications text;
alter table public.products add column if not exists storage_conditions text;
alter table public.products add column if not exists handling_notes text;
alter table public.products add column if not exists accessories_included text;
create index if not exists idx_products_tenant_gtin on public.products(tenant_id,gtin_ean) where gtin_ean is not null;
create index if not exists idx_products_tenant_anvisa on public.products(tenant_id,anvisa_register) where anvisa_register is not null;

create or replace function public.create_product_family(p_name text,p_code text default null) returns public.product_families language plpgsql security definer set search_path=public as $$ declare u public.profiles%rowtype; f public.product_families%rowtype; begin select * into u from public.profiles where id=auth.uid() and is_active=true; if not found then raise exception 'Usuário não autenticado ou inativo'; end if; if u.role_code not in ('SUPERADMIN','RESPONSAVEL_TECNICA','ADMIN_EMPRESA') then raise exception 'Perfil sem permissão para cadastrar famílias'; end if; if trim(coalesce(p_name,''))='' then raise exception 'Nome da família é obrigatório'; end if; select * into f from public.product_families where tenant_id=u.tenant_id and lower(name)=lower(trim(p_name)) limit 1; if found then return f; end if; insert into public.product_families(tenant_id,name,code) values(u.tenant_id,trim(p_name),nullif(upper(trim(p_code)),'')) returning * into f; return f; end $$;
revoke all on function public.create_product_family(text,text) from public; grant execute on function public.create_product_family(text,text) to authenticated;

create or replace function public.create_product_master(p_product jsonb)
returns public.products language plpgsql security definer set search_path=public as $$
declare v_profile public.profiles%rowtype; v_product public.products%rowtype; v_sku text; v_name text; begin
 select * into v_profile from public.profiles where id=auth.uid() and is_active=true; if not found then raise exception 'Usuário não autenticado ou inativo'; end if;
 if v_profile.role_code not in ('SUPERADMIN','RESPONSAVEL_TECNICA','ADMIN_EMPRESA') then raise exception 'Perfil sem permissão para cadastrar produtos'; end if;
 v_sku=upper(trim(coalesce(p_product->>'codeSku',''))); v_name=trim(coalesce(p_product->>'name','')); if v_sku='' then raise exception 'SKU é obrigatório'; end if; if v_name='' then raise exception 'Nome do produto é obrigatório'; end if;
 if exists(select 1 from public.products where tenant_id=v_profile.tenant_id and upper(code_sku)=v_sku) then raise exception 'Já existe produto com este SKU'; end if;
 insert into public.products(tenant_id,family_id,code_sku,name,description,model,anvisa_register,supplier_name,country_origin,brand,manufacturer_name,importer_name,distributor_name,image_url,is_active,updated_at,gtin_ean,ncm,unit_measure,manufacturer_reference,regulatory_type,anvisa_status,anvisa_expiration_date,anvisa_risk_class,inmetro_register,inmetro_expiration_date,udi_di,lot_control,serial_control,expiration_control,shelf_life_months,warranty_months,intended_use,technical_specifications,storage_conditions,handling_notes,accessories_included)
 values(v_profile.tenant_id,nullif(p_product->>'familyId','')::uuid,v_sku,v_name,nullif(trim(p_product->>'description'),''),nullif(trim(p_product->>'model'),''),nullif(trim(p_product->>'anvisaRegister'),''),nullif(trim(p_product->>'supplierName'),''),nullif(trim(p_product->>'countryOrigin'),''),nullif(trim(p_product->>'brand'),''),nullif(trim(p_product->>'manufacturerName'),''),nullif(trim(p_product->>'importerName'),''),nullif(trim(p_product->>'distributorName'),''),nullif(trim(p_product->>'imageUrl'),''),true,now(),nullif(trim(p_product->>'gtinEan'),''),nullif(trim(p_product->>'ncm'),''),nullif(trim(p_product->>'unitMeasure'),''),nullif(trim(p_product->>'manufacturerReference'),''),coalesce(nullif(trim(p_product->>'regulatoryType'),''),'ANVISA'),nullif(trim(p_product->>'anvisaStatus'),''),nullif(p_product->>'anvisaExpirationDate','')::date,nullif(trim(p_product->>'anvisaRiskClass'),''),nullif(trim(p_product->>'inmetroRegister'),''),nullif(p_product->>'inmetroExpirationDate','')::date,nullif(trim(p_product->>'udiDi'),''),coalesce((p_product->>'lotControl')::boolean,true),coalesce((p_product->>'serialControl')::boolean,false),coalesce((p_product->>'expirationControl')::boolean,false),nullif(p_product->>'shelfLifeMonths','')::integer,nullif(p_product->>'warrantyMonths','')::integer,nullif(trim(p_product->>'intendedUse'),''),nullif(trim(p_product->>'technicalSpecifications'),''),nullif(trim(p_product->>'storageConditions'),''),nullif(trim(p_product->>'handlingNotes'),''),nullif(trim(p_product->>'accessoriesIncluded'),'')) returning * into v_product;
 insert into public.audit_logs(tenant_id,user_id,user_email,action,entity,entity_id,details) values(v_product.tenant_id,v_profile.id,v_profile.email,'PRODUCT_MASTER_CREATED','PRODUCT',v_product.id,to_jsonb(v_product)); return v_product; end $$;

create or replace function public.update_product_master(p_product_id uuid,p_changes jsonb)
returns public.products language plpgsql security definer set search_path=public as $$
declare v_profile public.profiles%rowtype; v_product public.products%rowtype; v_before public.products%rowtype; begin
 select * into v_profile from public.profiles where id=auth.uid() and is_active=true; if not found then raise exception 'Usuário não autenticado ou inativo'; end if;
 if v_profile.role_code not in ('SUPERADMIN','RESPONSAVEL_TECNICA','ADMIN_EMPRESA') then raise exception 'Perfil sem permissão para alterar produtos'; end if;
 select * into v_before from public.products where id=p_product_id and (v_profile.role_code='SUPERADMIN' or tenant_id=v_profile.tenant_id); if not found then raise exception 'Produto não encontrado ou fora da empresa'; end if;
 if p_changes ? 'codeSku' and exists(select 1 from public.products where tenant_id=v_before.tenant_id and id<>p_product_id and upper(code_sku)=upper(trim(p_changes->>'codeSku'))) then raise exception 'Já existe produto com este SKU'; end if;
 update public.products set family_id=case when p_changes?'familyId' then nullif(p_changes->>'familyId','')::uuid else family_id end, code_sku=coalesce(nullif(upper(trim(p_changes->>'codeSku')),''),code_sku), name=coalesce(nullif(trim(p_changes->>'name'),''),name), description=case when p_changes?'description' then nullif(trim(p_changes->>'description'),'') else description end, model=case when p_changes?'model' then nullif(trim(p_changes->>'model'),'') else model end, anvisa_register=case when p_changes?'anvisaRegister' then nullif(trim(p_changes->>'anvisaRegister'),'') else anvisa_register end, supplier_name=case when p_changes?'supplierName' then nullif(trim(p_changes->>'supplierName'),'') else supplier_name end, country_origin=case when p_changes?'countryOrigin' then nullif(trim(p_changes->>'countryOrigin'),'') else country_origin end, brand=case when p_changes?'brand' then nullif(trim(p_changes->>'brand'),'') else brand end, manufacturer_name=case when p_changes?'manufacturerName' then nullif(trim(p_changes->>'manufacturerName'),'') else manufacturer_name end, importer_name=case when p_changes?'importerName' then nullif(trim(p_changes->>'importerName'),'') else importer_name end, distributor_name=case when p_changes?'distributorName' then nullif(trim(p_changes->>'distributorName'),'') else distributor_name end, image_url=case when p_changes?'imageUrl' then nullif(trim(p_changes->>'imageUrl'),'') else image_url end, gtin_ean=case when p_changes?'gtinEan' then nullif(trim(p_changes->>'gtinEan'),'') else gtin_ean end, ncm=case when p_changes?'ncm' then nullif(trim(p_changes->>'ncm'),'') else ncm end, unit_measure=case when p_changes?'unitMeasure' then nullif(trim(p_changes->>'unitMeasure'),'') else unit_measure end, manufacturer_reference=case when p_changes?'manufacturerReference' then nullif(trim(p_changes->>'manufacturerReference'),'') else manufacturer_reference end, regulatory_type=case when p_changes?'regulatoryType' then coalesce(nullif(trim(p_changes->>'regulatoryType'),''),'ANVISA') else regulatory_type end, anvisa_status=case when p_changes?'anvisaStatus' then nullif(trim(p_changes->>'anvisaStatus'),'') else anvisa_status end, anvisa_expiration_date=case when p_changes?'anvisaExpirationDate' then nullif(p_changes->>'anvisaExpirationDate','')::date else anvisa_expiration_date end, anvisa_risk_class=case when p_changes?'anvisaRiskClass' then nullif(trim(p_changes->>'anvisaRiskClass'),'') else anvisa_risk_class end, inmetro_register=case when p_changes?'inmetroRegister' then nullif(trim(p_changes->>'inmetroRegister'),'') else inmetro_register end, inmetro_expiration_date=case when p_changes?'inmetroExpirationDate' then nullif(p_changes->>'inmetroExpirationDate','')::date else inmetro_expiration_date end, udi_di=case when p_changes?'udiDi' then nullif(trim(p_changes->>'udiDi'),'') else udi_di end, lot_control=case when p_changes?'lotControl' then (p_changes->>'lotControl')::boolean else lot_control end, serial_control=case when p_changes?'serialControl' then (p_changes->>'serialControl')::boolean else serial_control end, expiration_control=case when p_changes?'expirationControl' then (p_changes->>'expirationControl')::boolean else expiration_control end, shelf_life_months=case when p_changes?'shelfLifeMonths' then nullif(p_changes->>'shelfLifeMonths','')::integer else shelf_life_months end, warranty_months=case when p_changes?'warrantyMonths' then nullif(p_changes->>'warrantyMonths','')::integer else warranty_months end, intended_use=case when p_changes?'intendedUse' then nullif(trim(p_changes->>'intendedUse'),'') else intended_use end, technical_specifications=case when p_changes?'technicalSpecifications' then nullif(trim(p_changes->>'technicalSpecifications'),'') else technical_specifications end, storage_conditions=case when p_changes?'storageConditions' then nullif(trim(p_changes->>'storageConditions'),'') else storage_conditions end, handling_notes=case when p_changes?'handlingNotes' then nullif(trim(p_changes->>'handlingNotes'),'') else handling_notes end, accessories_included=case when p_changes?'accessoriesIncluded' then nullif(trim(p_changes->>'accessoriesIncluded'),'') else accessories_included end, updated_at=now() where id=p_product_id returning * into v_product;
 insert into public.audit_logs(tenant_id,user_id,user_email,action,entity,entity_id,details) values(v_product.tenant_id,v_profile.id,v_profile.email,'PRODUCT_MASTER_UPDATED','PRODUCT',v_product.id,jsonb_build_object('before',to_jsonb(v_before),'after',to_jsonb(v_product))); return v_product; end $$;